export function getHistoricalRaceResults(year: number | string, round: number): HistoricalGrandPrixResults | null {
  const y = typeof year === 'string' ? parseInt(year, 10) : year;
  return HISTORICAL_RESULTS_BY_YEAR[y]?.[round] || null;
}
